INSERT INTO `game_tiers` (`tier`, `resolution`, `target_setting`, `target_fps`, `min_cpu_score`, `min_gpu_score`, `description`) VALUES
(1, '1080p', 'Low', 60, 2580, 3900, 'Cấu hình máy cỏ tiết kiệm nhất, đáp ứng vừa đủ để chơi mượt các game Esport cơ bản ở mức cài đặt thấp.'),
(1, '1080p', 'Medium', 60, 2580, 6363, 'Mức cấu hình phổ thông, chơi mượt mà không lo giật lag ở mức đồ họa trung bình.'),
(1, '1080p', 'High', 144, 3436, 7872, 'Chuẩn cấu hình Gaming cho game thủ Esport, đáp ứng màn hình 144Hz mượt mà trong giao tranh.'),
(1, '1080p', 'Ultra', 240, 3488, 12680, 'Combo Esports đỉnh cao, đẩy tối đa khung hình lên 240+ FPS để leo rank mượt mà nhất.'),
(1, '1440p', 'Medium', 60, 3436, 7872, 'Đáp ứng độ phân giải 2K sắc nét với mức chi phí tối ưu, đồ họa trung bình ổn định.'),
(1, '1440p', 'High', 144, 3488, 12495, 'Trải nghiệm Esport 2K 144Hz cực mượt, hình ảnh vừa sắc nét vừa không trễ nải.'),
(1, '1440p', 'Ultra', 240, 3633, 16981, 'Cấu hình tối thượng cho màn hình Gaming 2K 240Hz, cân mượt mọi game Esport ở mức Ultra.'),
(1, '4K', 'Medium', 60, 3488, 14091, 'Bắt đầu trải nghiệm độ phân giải 4K trên màn hình lớn với mức FPS ổn định.'),
(1, '4K', 'High', 60, 3488, 16981, 'Hình ảnh game Esport sắc nét đến từng chi tiết trên màn 4K High Setting.'),
(1, '4K', 'Ultra', 144, 3704, 19508, 'Đỉnh cao giải trí Esport, gánh mượt mà màn hình 4K tần số quét cao 144Hz.'),
(2, '1080p', 'Low', 60, 2580, 6363, 'Cấu hình tối giản để chiến các tựa game 3D thế giới mở phổ thông ổn định ở 60 FPS.'),
(2, '1080p', 'Medium', 60, 3436, 12680, 'Mức đồ họa trung bình, cân bằng tốt giữa chi phí và trải nghiệm hình ảnh 3D.'),
(2, '1080p', 'High', 60, 3488, 12495, 'Trải nghiệm hình ảnh đẹp, đổ bóng và chi tiết vật thể rõ nét ổn định mượt mà.'),
(2, '1080p', 'Ultra', 144, 3633, 19508, 'Combo quốc dân cho game 3D thế giới mở, hình ảnh đẹp nhất kèm FPS cao mượt mà.'),
(2, '1440p', 'Medium', 60, 3488, 16981, 'Độ phân giải 2K tiêu chuẩn, hình ảnh mịn màng, cấu hình kinh tế.'),
(2, '1440p', 'High', 60, 3633, 19508, 'Đẩy mạnh hiệu năng card đồ họa để tối ưu hóa hình ảnh trên màn hình 2K sắc nét.'),
(2, '1440p', 'Ultra', 144, 4268, 22610, 'Cấu hình hoàn hảo cho game thủ thích thế giới mở trên màn hình 2K tần số quét cao.'),
(2, '4K', 'Medium', 60, 3633, 22610, 'Tận hưởng thế giới game 3D rộng lớn ở độ phân giải 4K với mức chi phí hợp lý.'),
(2, '4K', 'High', 60, 4268, 26900, 'Sự kết hợp phần cứng mạnh mẽ giúp xử lý lượng điểm ảnh khổng lồ của màn 4K.'),
(2, '4K', 'Ultra', 60, 4458, 29955, 'Trải nghiệm game đồ họa 3D căng nét, thiết lập Ultra tối đa trên màn hình 4K.'),
(3, '1080p', 'Low', 60, 3436, 12680, 'Cấu hình cơ bản nhất để làm quen với các bom tấn AAA mà không bị giật lag.'),
(3, '1080p', 'Medium', 60, 3488, 14091, 'Mức thiết lập trung bình giúp bạn trải nghiệm cốt truyện game AAA mượt mà, ổn định.'),
(3, '1080p', 'High', 60, 3488, 16981, 'Hình ảnh bom tấn AAA hiện lên sống động, chi tiết vật thể cao ở độ phân giải FHD.'),
(3, '1080p', 'Ultra', 60, 3633, 19508, 'Cấu hình tiêu chuẩn để cày nát các game AAA ở mức thiết lập đồ họa cao nhất.'),
(3, '1440p', 'Medium', 60, 3488, 19508, 'Trải nghiệm không gian game AAA rộng lớn, sắc nét trên màn hình 2K Medium Setting.'),
(3, '1440p', 'High', 60, 4268, 22610, 'Đồ họa cực kỳ mãn nhãn, cân bằng hoàn hảo giữa độ chi tiết hình ảnh và hiệu năng.'),
(3, '1440p', 'Ultra', 60, 4268, 29955, 'Combo lý tưởng cho game thủ AAA chân chính, quẩy mượt mọi bom tấn đồ họa ở màn 2K Ultra.'),
(3, '4K', 'Medium', 60, 4268, 29955, 'Bước vào kỷ nguyên gaming 4K bom tấn với khung hình ổn định chuẩn 60 FPS.'),
(3, '4K', 'High', 60, 4458, 31817, 'Sức mạnh phần cứng vượt trội, xử lý mượt mà các texture siêu nặng của game AAA ở màn 4K.'),
(3, '4K', 'Ultra', 60, 4458, 34265, 'Quái vật phần cứng thực sự, chuyên dụng để chinh phục đỉnh cao đồ họa 4K Ultra khắt khe nhất.'),
(4, '1080p', 'Medium', 60, 3633, 22610, 'Kích hoạt Ray Tracing cơ bản ở độ phân giải FHD, mang lại ánh sáng chân thực.'),
(4, '1080p', 'Ultra', 60, 4268, 26900, 'Mở khóa toàn bộ công nghệ Ray Tracing nặng đô nhất ở màn hình FHD với 60+ FPS.'),
(4, '1440p', 'Medium', 60, 4268, 26900, 'Trải nghiệm Ray Tracing sắc nét trên màn 2K, đổ bóng và phản chiếu cực kỳ chân thực.'),
(4, '1440p', 'Ultra', 60, 4458, 31817, 'Đỉnh cao gaming 2K, gánh mượt mà các công nghệ hình ảnh giả lập ánh sáng vật lý phức tạp.'),
(4, '4K', 'Medium', 60, 4458, 34265, 'Cấu hình siêu cấp cao, mang rạp phim về nhà với công nghệ Ray Tracing trên màn 4K.'),
(4, '4K', 'Ultra', 60, 4690, 38077, 'Cấu hình tối thượng, chuyên trị Path Tracing/Ray Tracing toàn phần ở độ phân giải 4K.');
