INSERT INTO `messages` (`id`, `conversation_id`, `role`, `content`, `intent`, `created_at`) VALUES
(890, 286, 'bot', 'Với ngân sách **10.000 USD** và yêu cầu sử dụng card đồ họa **RTX 5090**, đây là cấu hình **PC gaming** cao cấp nhất tôi đề xuất cho bạn:\n\n- **CPU**: AMD Ryzen 9 9950X3D2\n- **Mainboard**: Asus ROG STRIX B850-A GAMING WIFI\n- **GPU**: MSI SUPRIM LIQUID SOC GeForce RTX 5090 32 GB\n- **RAM**: G.Skill Trident Z5 RGB 64 GB\n- **Storage**: Seagate FireCuda 530\n- **CPU Cooler**: Corsair iCUE H170i ELITE CAPELLIX\n- **PSU**: Corsair HX1200i\n- **Case**: Azza Cube 802 RGB\n\nTổng chi phí ước tính cho cấu hình này là khoảng **6.805 USD**. Bạn có muốn thay đổi linh kiện nào hoặc cần kiểm tra tính tương thích chi tiết hơn không?', 'build pc', '2026-05-30 02:13:23'),
