INSERT INTO `messages` (`id`, `conversation_id`, `role`, `content`, `intent`, `created_at`) VALUES
(1255, 392, 'bot', 'Dưới đây là cấu hình **PC gaming** tối ưu trong tầm giá **1000 USD**:\n\n- **CPU**: Intel Core Ultra 7 265KF\n- **Mainboard**: ASRock B860 Rock WiFi 7\n- **GPU**: MSI GAMING TRIO OC GeForce RTX 5060 8 GB\n- **RAM**: Crucial 32 GB\n- **Storage**: Samsung 970 Evo Plus\n- **CPU Cooler**: ARCTIC Freezer 36\n- **PSU**: MSI MAG A550BN\n- **Case**: DIYPC MA08\n\nTổng chi phí ước tính là **985.65 USD**.', 'build pc', '2026-06-17 02:50:53'),
(1256, 392, 'user', 'đổi qua cpu amd', NULL, '2026-06-17 02:51:14'),
(1257, 392, 'bot', 'Dưới đây là cấu hình **PC gaming** sử dụng **CPU AMD** với ngân sách khoảng **1000 USD**:\n\n- **CPU**: AMD Ryzen 5 9600\n- **Mainboard**: MSI PRO B650M-P\n- **GPU**: MSI GAMING TRIO OC GeForce RTX 5060 8 GB\n- **RAM**: Crucial 32 GB\n- **Storage**: Samsung 970 Evo Plus\n- **CPU Cooler**: ARCTIC Freezer A35\n- **PSU**: CoolMax V-400\n- **Case**: SAMA Sama-S88-BK\n\nTổng chi phí ước tính là **1014.05 USD**.', 'build pc', '2026-06-17 02:51:22'),
(1258, 392, 'user', 'So sánh hiệu năng CPU Intel và AMD này', NULL, '2026-06-17 02:51:32'),
(1259, 392, 'bot', 'Dưới đây là so sánh giữa **Intel Core Ultra 7 265KF** và **AMD Ryzen 5 9600**:\n\n- **Intel Core Ultra 7 265KF**: Sở hữu **20 nhân**, xung nhịp boost lên tới **5.5 GHz**. Hiệu năng đa nhân vượt trội hơn **100.1%** và đơn nhân cao hơn **12.6%** so với AMD.\n- **AMD Ryzen 5 9600**: Có **6 nhân**, xung nhịp boost **5.2 GHz**. Ưu điểm là mức tiêu thụ điện năng thấp hơn (**65W** so với **125W**) và tích hợp sẵn đồ họa **Radeon**.\n\n**Kết luận**: Nếu bạn ưu tiên hiệu năng xử lý mạnh mẽ cho các tác vụ nặng, **Intel Core Ultra 7 265KF** là lựa chọn tốt hơn. Nếu bạn muốn tiết kiệm điện năng và không cần card đồ họa rời ngay lập tức, **AMD Ryzen 5 9600** là phương án hợp lý.', 'compare', '2026-06-17 02:51:39'),
(1260, 393, 'user', 'Gợi ý cấu hình PC chơi game giá tầm 1000 USD', NULL, '2026-06-17 03:02:44'),
