INSERT INTO `shop_faq` (`faq_id`, `question`, `answer`, `category`, `created_at`, `updated_at`) VALUES
(1, 'Shop có mã giảm giá không?', 'Shop thường xuyên triển khai các chương trình khuyến mãi theo từng thời điểm. Vui lòng theo dõi website hoặc liên hệ nhân viên để nhận thông tin mới nhất.', 'Promotion', '2026-06-22 10:50:13', '2026-06-22 10:50:13'),
(2, 'Làm sao để nhận mã giảm giá?', 'Hiển thị trực tiếp trên website khi nhập mã giảm giá.', 'Promotion', '2026-06-22 10:50:13', '2026-06-22 10:50:13'),
(3, 'Có thể dùng nhiều mã giảm giá cùng lúc không?', 'Mỗi đơn hàng chỉ áp dụng một mã giảm giá, trừ khi chương trình có quy định khác.', 'Promotion', '2026-06-22 10:50:13', '2026-06-22 10:50:13'),
(4, 'Shop có giao hàng toàn quốc không?', 'Shop hỗ trợ giao hàng trên toàn quốc thông qua các đơn vị vận chuyển đối tác.', 'Shipping', '2026-06-22 10:50:13', '2026-06-22 10:50:13'),
(5, 'Phí vận chuyển được tính như thế nào?', 'Phí vận chuyển phụ thuộc vào địa chỉ nhận hàng, trọng lượng sản phẩm và đơn vị vận chuyển.', 'Shipping', '2026-06-22 10:50:13', '2026-06-22 10:50:13'),
(6, 'Bao lâu tôi nhận được hàng?', 'Thời gian giao hàng thường từ 1–5 ngày làm việc tùy khu vực.', 'Shipping', '2026-06-22 10:50:13', '2026-06-22 10:50:13'),
(7, 'Tôi có thể kiểm tra tình trạng đơn hàng không?', 'Có, khách hàng có thể liên hệ shop để được hỗ trợ tra cứu tình trạng đơn hàng.', 'Shipping', '2026-06-22 10:50:13', '2026-06-22 10:50:13'),
(8, 'Shop hỗ trợ những hình thức thanh toán nào?', 'Shop hỗ trợ thanh toán khi nhận hàng (COD), chuyển khoản ngân hàng và thanh toán trực tuyến.', 'Payment', '2026-06-22 10:50:13', '2026-06-22 10:50:13'),
(9, 'Tôi có thể thanh toán bằng chuyển khoản không?', 'Có, thông tin tài khoản ngân hàng sẽ được cung cấp khi xác nhận đơn hàng.', 'Payment', '2026-06-22 10:50:13', '2026-06-22 10:50:13'),
(10, 'Shop có hỗ trợ trả góp không?', 'Shop hỗ trợ trả góp qua các đối tác tài chính hoặc thẻ tín dụng tùy chương trình áp dụng.', 'Installment', '2026-06-22 10:50:13', '2026-06-22 10:50:13'),
(11, 'Điều kiện để trả góp là gì?', 'Điều kiện trả góp phụ thuộc vào đơn vị tài chính và quy định tại thời điểm mua hàng.', 'Installment', '2026-06-22 10:50:13', '2026-06-22 10:50:13'),
(12, 'Sản phẩm được bảo hành bao lâu?', 'Thời gian bảo hành phụ thuộc vào từng sản phẩm và chính sách của nhà sản xuất.', 'Warranty', '2026-06-22 10:50:13', '2026-06-22 10:50:13'),
(13, 'Làm sao để kiểm tra thời hạn bảo hành?', 'Thông tin bảo hành được hiển thị trên trang sản phẩm hoặc phiếu bảo hành đi kèm.', 'Warranty', '2026-06-22 10:50:13', '2026-06-22 10:50:13'),
(14, 'Tôi cần làm gì khi sản phẩm bị lỗi?', 'Vui lòng liên hệ bộ phận hỗ trợ khách hàng để được hướng dẫn kiểm tra và bảo hành.', 'Warranty', '2026-06-22 10:50:13', '2026-06-22 10:50:13'),
(15, 'Shop có hỗ trợ đổi trả không?', 'Shop hỗ trợ đổi trả theo chính sách hiện hành đối với sản phẩm đủ điều kiện.', 'Return', '2026-06-22 10:50:13', '2026-06-22 10:50:13'),
(16, 'Trong bao lâu tôi có thể yêu cầu đổi trả?', 'Thời hạn đổi trả phụ thuộc vào chính sách áp dụng tại thời điểm mua hàng.', 'Return', '2026-06-22 10:50:13', '2026-06-22 10:50:13'),
(17, 'Sản phẩm đã sử dụng có được đổi trả không?', 'Việc đổi trả sản phẩm đã sử dụng sẽ được xem xét theo tình trạng thực tế và chính sách của shop.', 'Return', '2026-06-22 10:50:13', '2026-06-22 10:50:13'),
(18, 'Shop có bán linh kiện cũ không?', 'Không, shop chỉ kinh doanh sản phẩm mới chính hãng.', 'Products', '2026-06-22 10:50:13', '2026-06-22 10:50:13'),
(19, 'Sản phẩm có phải hàng chính hãng không?', 'Tất cả sản phẩm đều là hàng chính hãng từ các nhà phân phối uy tín.', 'Products', '2026-06-22 10:50:13', '2026-06-22 10:50:13'),
(20, 'Sản phẩm có sẵn hàng không?', 'Tình trạng tồn kho được cập nhật trên hệ thống và có thể thay đổi theo thời điểm.', 'Products', '2026-06-22 10:50:13', '2026-06-22 10:50:13'),
(21, 'Shop có hỗ trợ tư vấn build PC không?', 'Có, hệ thống AI và đội ngũ tư vấn sẽ hỗ trợ lựa chọn cấu hình phù hợp với nhu cầu và ngân sách.', 'Support', '2026-06-22 10:50:13', '2026-06-22 10:50:13'),
(22, 'Shop có kiểm tra tương thích linh kiện không?', 'Có, hệ thống có thể kiểm tra tính tương thích giữa CPU, mainboard, RAM, PSU và các linh kiện khác.', 'Support', '2026-06-22 10:50:13', '2026-06-22 10:50:13'),
(23, 'Tôi không rành về PC thì có được tư vấn không?', 'Có, shop hỗ trợ tư vấn từ cơ bản đến nâng cao để giúp khách hàng lựa chọn cấu hình phù hợp.', 'Support', '2026-06-22 10:50:13', '2026-06-22 10:50:13'),
(24, 'Làm sao để liên hệ với shop?', 'Khách hàng có thể liên hệ qua hotline, email hoặc fanpage của shop.', 'Contact', '2026-06-22 10:50:13', '2026-06-22 10:50:13'),
(25, 'Shop làm việc vào thời gian nào?', 'Thời gian làm việc được công bố trên website và các kênh chính thức của shop.', 'Contact', '2026-06-22 10:50:13', '2026-06-22 10:50:13');
