INSERT INTO `software_tiers` (`tier`, `workload_scale`, `min_cpu`, `min_gpu`, `description`) VALUES
(1, 'Basic', 3436, 4984, 'Cấu hình tối giản đáp ứng các thao tác làm việc văn phòng cơ bản hoặc học thuật lập trình nhập môn.'),
(1, 'Intermediate', 3436, 6363, 'Mức cấu hình khuyên dùng cho dân thiết kế đồ họa 2D nhẹ nhàng và lập trình web mượt mà ổn định.'),
(1, 'Professional', 3488, 7872, 'Xử lý tốt các file thiết kế 2D nặng nhiều layer liên tục trong thời gian dài mà không lo khựng lag.'),
(2, 'Basic', 3436, 7872, 'Đáp ứng ở mức vừa đủ để chạy các IDE lập trình chuyên dụng hoặc edit video ngắn FullHD 1080p cơ bản.'),
(2, 'Intermediate', 3488, 12680, 'Combo khuyên dùng để làm việc đồ họa 3D tầm trung đa nhiệm tốt và biên dịch build code mượt mà.'),
(2, 'Professional', 3633, 16981, 'Gánh tải nặng khi xử lý render video FullHD liên tục hoặc chạy song song nhiều máy ảo emulator để test app.'),
(3, 'Basic', 3488, 10760, 'Cấu hình nền tảng để bắt đầu làm quen với các dự án dựng hình 3D kỹ thuật hoặc edit video 4K ở mức độ vừa phải.'),
(3, 'Intermediate', 4268, 16981, 'Cấu hình tiêu chuẩn lý tưởng cho dân DevOps chạy Docker mượt mà hoặc editor preview video 4K thời gian thực ổn định.'),
(3, 'Professional', 4458, 19508, 'Quá tải các project cơ sở dữ liệu lớn microservices nặng hoặc rút ngắn tối đa thời gian render các cảnh 3D phức tạp.'),
(4, 'Basic', 4268, 22610, 'Đáp ứng bước đầu cho môi trường phát triển game nặng như Unreal Engine 5 hoặc chạy các thuật toán AI quy mô nhỏ.'),
(4, 'Intermediate', 4458, 31817, 'Cấu hình mạnh mẽ khuyên dùng cho kiến trúc sư render Lumion cảnh lớn hoặc kỹ sư train model AI dữ liệu lớn local.'),
(4, 'Professional', 4690, 34265, 'Quái vật phần cứng tối thượng gánh mọi tác vụ ảo hóa doanh nghiệp đa máy ảo hoặc training deep learning siêu tốc.');
